    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $mod = 100000;
        $limit = 10000000000;

        $count2 = 0;
        $count5 = 0;
        $suffix = 1;
        $small = 1;
        $tooLarge = false;
        $logSum = 0.0;

        for ($i = $left; $i <= $right; $i++) {
            $value = $i;

            while ($value % 2 === 0) {
                $count2++;
                $value = intdiv($value, 2);
            }

            while ($value % 5 === 0) {
                $count5++;
                $value = intdiv($value, 5);
            }

            $suffix = ($suffix * ($value % $mod)) % $mod;

            if ($value > 1) {
                $logSum += log10($value);

                if (!$tooLarge) {
                    if ($small > intdiv($limit - 1, $value)) {
                        $tooLarge = true;
                    } else {
                        $small *= $value;
                    }
                }
            }
        }

        $zeros = min($count2, $count5);
        $extra2 = $count2 - $zeros;
        $extra5 = $count5 - $zeros;

        $modPow = function ($base, $exponent) use ($mod) {
            $result = 1;
            $base %= $mod;

            while ($exponent > 0) {
                if ($exponent % 2 === 1) {
                    $result = ($result * $base) % $mod;
                }
                $base = ($base * $base) % $mod;
                $exponent = intdiv($exponent, 2);
            }

            return $result;
        };

        if ($extra2 > 0) {
            $suffix = ($suffix * $modPow(2, $extra2)) % $mod;
            $logSum += $extra2 * log10(2);

            if (!$tooLarge) {
                for ($i = 0; $i < $extra2; $i++) {
                    if ($small > intdiv($limit - 1, 2)) {
                        $tooLarge = true;
                        break;
                    }
                    $small *= 2;
                }
            }
        }

        if ($extra5 > 0) {
            $suffix = ($suffix * $modPow(5, $extra5)) % $mod;
            $logSum += $extra5 * log10(5);

            if (!$tooLarge) {
                for ($i = 0; $i < $extra5; $i++) {
                    if ($small > intdiv($limit - 1, 5)) {
                        $tooLarge = true;
                        break;
                    }
                    $small *= 5;
                }
            }
        }

        if (!$tooLarge) {
            return $small . 'e' . $zeros;
        }

        $fraction = $logSum - floor($logSum);
        $prefix = (int) floor(pow(10, $fraction + 4));

        if ($prefix >= 100000) {
            $prefix = 99999;
        }

        return $prefix . '...' . sprintf('%05d', $suffix) . 'e' . $zeros;
    }
}
