     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $mod = 1000000007;
        sort($arr, SORT_NUMERIC);

        $n = count($arr);
        $index = [];
        $dp = array_fill(0, $n, 1);

        for ($i = 0; $i < $n; $i++) {
            $index[$arr[$i]] = $i;
