        $frequency2 = array_fill(0, 26, 0);

        for ($i = 0, $length = strlen($word1); $i < $length; $i++) {
            $frequency1[ord($word1[$i]) - ord('a')]++;
            $frequency2[ord($word2[$i]) - ord('a')]++;
