<?php

class MKAverage {
    private $m;
    private $k;
    private $limit = 100000;
    private $countTree;
    private $sumTree;
    private $queue = [];
    private $head = 0;
    private $size = 0;

    /**
     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->countTree = array_fill(0, $this->limit + 1, 0);
        $this->sumTree = array_fill(0, $this->limit + 1, 0);
    }

    /**
     * @param Integer $num
     * @return NULL
     */
    function addElement($num) {
        $this->queue[] = $num;
        $this->size++;

        $this->update($num, 1);

        if ($this->size > $this->m) {
            $removed = $this->queue[$this->head];
            unset($this->queue[$this->head]);
            $this->head++;
            $this->size--;

            $this->update($removed, -1);
        }

        return null;
    }

    /**
     * @return Integer
     */
    function calculateMKAverage() {
        if ($this->size < $this->m) {
            return -1;
        }

        $sumThroughUpperBoundary = $this->sumSmallest($this->m - $this->k);
        $sumThroughLowerBoundary = $this->sumSmallest($this->k);
        $middleSum = $sumThroughUpperBoundary - $sumThroughLowerBoundary;

        return intdiv($middleSum, $this->m - 2 * $this->k);
    }

    private function update($value, $delta) {
        for ($i = $value; $i <= $this->limit; $i += $i & (-$i)) {
            $this->countTree[$i] += $delta;
            $this->sumTree[$i] += $delta * $value;
        }
    }

    private function sumSmallest($requiredCount) {
        if ($requiredCount <= 0) {
            return 0;
        }

        $position = 0;
        $currentCount = 0;
        $currentSum = 0;
        $step = 1;

        while (($step << 1) <= $this->limit) {
            $step <<= 1;
        }

        for (; $step > 0; $step >>= 1) {
            $next = $position + $step;

            if (
                $next <= $this->limit &&
                $currentCount + $this->countTree[$next] < $requiredCount
            ) {
                $position = $next;
                $currentCount += $this->countTree[$next];
                $currentSum += $this->sumTree[$next];
            }
        }

        $targetValue = $position + 1;
        return $currentSum + ($requiredCount - $currentCount) * $targetValue;
    }
}
