                    $steps = $rightPos - $startPos;
                } else {
                    $leftDistance = $startPos - $leftPos;
                    $rightDistance = $rightPos - $startPos;
                    $steps = min(
                        2 * $leftDistance + $rightDistance,
                        $leftDistance + 2 * $rightDistance
                    );
