class Solution {

    /**
     * @param Integer $maxTime
     * @param Integer[][] $edges
     * @param Integer[] $passingFees
     * @return Integer
     */
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $graph = array_fill(0, $n, []);

        foreach ($edges as $edge) {
            [$u, $v, $time] = $edge;
            $graph[$u][] = [$v, $time];
            $graph[$v][] = [$u, $time];
        }

        $minTime = array_fill(0, $n, PHP_INT_MAX);

        $queue = new SplPriorityQueue();
        $queue->setExtractFlags(SplPriorityQueue::EXTR_DATA);
        $queue->insert([0, 0, $passingFees[0]], -$passingFees[0]);

        while (!$queue->isEmpty()) {
            [$city, $time, $cost] = $queue->extract();

            if ($time >= $minTime[$city]) {
                continue;
            }

            $minTime[$city] = $time;

            if ($city === $n - 1) {
                return $cost;
            }

            foreach ($graph[$city] as [$nextCity, $travelTime]) {
                $nextTime = $time + $travelTime;

                if ($nextTime > $maxTime || $nextTime >= $minTime[$nextCity]) {
                    continue;
                }

                $nextCost = $cost + $passingFees[$nextCity];
                $queue->insert(
                    [$nextCity, $nextTime, $nextCost],
                    -$nextCost
                );
            }
        }

        return -1;
    }
}
