        $queue->enqueue($root);
        $depth = 1;

        while (!$queue->isEmpty()) {
            $levelSize = $queue->count();

            for ($i = 0; $i < $levelSize; $i++) {
                $node = $queue->dequeue();

                if ($node->left === null && $node->right === null) {
