    function numOfWays($nums) {
        $mod = 1000000007;
        $n = count($nums);

        $power = function ($base, $exponent) use ($mod) {
            $result = 1;

            while ($exponent > 0) {
                if (($exponent & 1) === 1) {
                    $result = ($result * $base) % $mod;
                }
                $base = ($base * $base) % $mod;
                $exponent = intdiv($exponent, 2);
            }

            return $result;
        };

        $factorial = array_fill(0, $n + 1, 1);
        for ($i = 1; $i <= $n; $i++) {
            $factorial[$i] = ($factorial[$i - 1] * $i) % $mod;
        }

        $inverseFactorial = array_fill(0, $n + 1, 1);
        $inverseFactorial[$n] = $power($factorial[$n], $mod - 2);

        for ($i = $n; $i >= 1; $i--) {
            $inverseFactorial[$i - 1] =
                ($inverseFactorial[$i] * $i) % $mod;
        }

        $left = array_fill(0, $n, -1);
        $right = array_fill(0, $n, -1);

        for ($i = 1; $i < $n; $i++) {
            $current = 0;

            while (true) {
                if ($nums[$i] < $nums[$current]) {
                    if ($left[$current] === -1) {
                        $left[$current] = $i;
                        break;
                    }
                    $current = $left[$current];
                } else {
                    if ($right[$current] === -1) {
                        $right[$current] = $i;
                        break;
                    }
                    $current = $right[$current];
                }
            }
        }

        $subtreeSize = array_fill(0, $n, 0);
        $ways = array_fill(0, $n, 1);

        for ($i = $n - 1; $i >= 0; $i--) {
            $leftNode = $left[$i];
            $rightNode = $right[$i];

            $leftSize = $leftNode === -1 ? 0 : $subtreeSize[$leftNode];
            $rightSize = $rightNode === -1 ? 0 : $subtreeSize[$rightNode];

            $leftWays = $leftNode === -1 ? 1 : $ways[$leftNode];
            $rightWays = $rightNode === -1 ? 1 : $ways[$rightNode];

            $combinations = $factorial[$leftSize + $rightSize];
            $combinations =
                ($combinations * $inverseFactorial[$leftSize]) % $mod;
            $combinations =
                ($combinations * $inverseFactorial[$rightSize]) % $mod;

            $ways[$i] = ($combinations * $leftWays) % $mod;
            $ways[$i] = ($ways[$i] * $rightWays) % $mod;
            $subtreeSize[$i] = $leftSize + $rightSize + 1;
        }

        return ($ways[0] - 1 + $mod) % $mod;
    }
