    function maxSizeSlices($slices) {
        $length = count($slices);
        $picks = intdiv($length, 3);

        $solveLinear = function ($values) use ($picks) {
            $negativeInfinity = -1000000000000000;

            $previousTwo = array_fill(0, $picks + 1, $negativeInfinity);
            $previousOne = array_fill(0, $picks + 1, $negativeInfinity);
            $previousTwo[0] = 0;
            $previousOne[0] = 0;

            foreach ($values as $value) {
                $current = $previousOne;

                for ($chosen = 1; $chosen <= $picks; $chosen++) {
                    $current[$chosen] = max(
                        $previousOne[$chosen],
                        $previousTwo[$chosen - 1] + $value
                    );
                }

                $previousTwo = $previousOne;
                $previousOne = $current;
            }

            return $previousOne[$picks];
        };

        $excludeLast = array_slice($slices, 0, $length - 1);
        $excludeFirst = array_slice($slices, 1);

        return max(
            $solveLinear($excludeLast),
            $solveLinear($excludeFirst)
        );
    }
}
