class Solution {

    private $memo = [];

    /**
     * @param Integer $n
     * @param Integer $firstPlayer
     * @param Integer $secondPlayer
     * @return Integer[]
     */
    function earliestAndLatest($n, $firstPlayer, $secondPlayer) {
        $this->memo = [];
        return $this->solve($n, $firstPlayer, $secondPlayer);
    }

    private function solve($n, $a, $b) {
        if ($a + $b > $n + 1) {
            $newA = $n + 1 - $b;
            $newB = $n + 1 - $a;
            $a = $newA;
            $b = $newB;
        }

        if ($a + $b === $n + 1) {
            return [1, 1];
        }

        $key = $n . ',' . $a . ',' . $b;
        if (isset($this->memo[$key])) {
            return $this->memo[$key];
        }

        $groups = [];
        $pairCount = intdiv($n, 2);

        for ($i = 1; $i <= $pairCount; $i++) {
            $j = $n + 1 - $i;

            if ($i === $a || $j === $a) {
                $groups[] = [$a];
            } elseif ($i === $b || $j === $b) {
                $groups[] = [$b];
            } else {
                $groups[] = [$i, $j];
            }
        }

        if ($n % 2 === 1) {
            $groups[] = [intdiv($n, 2) + 1];
        }

        $states = ['0,0' => [0, 0]];

        foreach ($groups as $choices) {
            $nextStates = [];

            foreach ($states as $state) {
                foreach ($choices as $winner) {
                    $beforeA = $state[0];
                    $between = $state[1];

                    if ($winner < $a) {
                        $beforeA++;
                    } elseif ($winner > $a && $winner < $b) {
                        $between++;
                    }

                    $stateKey = $beforeA . ',' . $between;
                    $nextStates[$stateKey] = [$beforeA, $between];
                }
            }

            $states = $nextStates;
        }

        $nextN = intdiv($n + 1, 2);
        $earliest = PHP_INT_MAX;
        $latest = 0;

        foreach ($states as $state) {
            $nextA = $state[0] + 1;
            $nextB = $state[0] + $state[1] + 2;

            $result = $this->solve($nextN, $nextA, $nextB);
            $earliest = min($earliest, $result[0] + 1);
            $latest = max($latest, $result[1] + 1);
        }

        return $this->memo[$key] = [$earliest, $latest];
    }
}
