            $requiredDigit = $sum % 10;
            $carry = intdiv($sum, 10);
            $resultChar = $result[$resultLength - 1 - $column];

            if (isset($mapping[$resultChar])) {
                if ($mapping[$resultChar] !== $requiredDigit) {
                    return false;
                }

                return $dfs($column + 1, 0, $carry);
            }

            if ($used[$requiredDigit]) {
